(function(){
  function substituirSkeleton(containerId, htmlReal){
    var container = document.getElementById(containerId);
    if(!container) return;
    var skeleton = container.querySelector('[data-skeleton]');
    if(skeleton) skeleton.remove();
    container.insertAdjacentHTML('beforeend', htmlReal);
  }
  /* Exemplo de uso:
     substituirSkeleton('posts-container', '<article>...</article>');
  */
  window.slSkeleton = { substituir: substituirSkeleton };
})();
